        },
        {
            "code": "DSS_ABOUT_PURPOSE_INFO",
            "message": "The Health Campaign Management DIGIT Dashboard is a Decision Support System (DSS) tool that provides health campaign management teams with a consolidated and interactive dashboard. The dashboard presents key metrics in a visually appealing format, making it easier for users to understand campaign progress, stock efficiency, and areas for improvement.",
            "module": "rainmaker-hcm-dss",
